const CATEGORY_ASSETS=Object.freeze({
  "/assets/category/deniz-urunleri.webp":"",
  "/assets/category/donuk-urunler.webp":"",
  "/assets/category/et-urunleri.webp":"",
  "/assets/category/sut-sarkuteri.webp":"",
  "/assets/category/yaglar.webp":"",
  "/assets/category/sos-konserve.webp":"",
  "/assets/category/bakliyat.webp":"",
  "/assets/category/baharat-cesni.webp":""
});

function embeddedCategoryAsset(path){
  const b64=CATEGORY_ASSETS[path];
  if(!b64)return null;
  const raw=atob(b64),bytes=new Uint8Array(raw.length);
  for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);
  return new Response(bytes,{headers:{
    "content-type":"image/webp",
    "cache-control":"public, max-age=31536000, immutable",
    "content-length":String(bytes.length)
  }});
}
