function productCard(p){
  const image=p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}" loading="lazy" decoding="async">`:`<span>Ürün görseli</span>`;
  const price=p.price_mode==="FIXED"&&p.price!=null?`${Number(p.price).toLocaleString("tr-TR")} ₺`:"Fiyat için teklif alın";
  return `<article class="product" data-product-card data-id="${esc(p.id)}" data-name="${esc(p.name)}" data-unit="${esc(p.unit||"Adet")}"><div class="pic">${image}</div><span class="badge">${esc(p.category||"Ürün")}</span><h3>${esc(p.name)}</h3><div class="meta">${esc(p.pack_text||p.net_qty||p.unit||"")}</div><div class="price">${price}</div><div class="stock">● ${p.stock_status==="OUT"?"Sipariş üzerine":"Stok / tedarik sinyali mevcut"}</div><div class="qty"><button type="button" data-dec>−</button><input data-qty value="1" inputmode="decimal" aria-label="Miktar"><button type="button" data-inc>+</button></div><button class="add" type="button" data-add>Teklif Listeme Ekle</button></article>`;
}
async function products(env,filters={}){
  await ensureCoreSchema(env);
  const db=env.DB; let sql=`SELECT * FROM products WHERE active=1`; const args=[];
  if(filters.category){sql+=` AND category=?`;args.push(filters.category)}
  if(filters.q){sql+=` AND (name LIKE ? OR category LIKE ? OR brand LIKE ?)`;const q=`%${filters.q}%`;args.push(q,q,q)}
  sql+=` ORDER BY sort_order,name LIMIT 200`;
  const r=await db.prepare(sql).bind(...args).all(); return r.results||[];
}
