function cartScript(){
return `<script>
(()=>{const KEY="okyQuoteCartV2";let cart={};try{cart=JSON.parse(localStorage.getItem(KEY)||"{}")}catch{}const counts=()=>document.querySelectorAll("[data-cart-count]").forEach(x=>x.textContent=Object.keys(cart).length);function save(){localStorage.setItem(KEY,JSON.stringify(cart));counts();render()}function open(){document.getElementById("drawer").classList.add("open");document.getElementById("overlay").classList.add("show");render()}function close(){document.getElementById("drawer").classList.remove("open");document.getElementById("overlay").classList.remove("show")}document.querySelectorAll("[data-open-quote]").forEach(x=>x.addEventListener("click",e=>{e.preventDefault();open()}));document.querySelector("[data-close-drawer]")?.addEventListener("click",close);document.getElementById("overlay")?.addEventListener("click",close);document.querySelectorAll("[data-product-card]").forEach(card=>{const input=card.querySelector("[data-qty]");card.querySelector("[data-inc]")?.addEventListener("click",()=>input.value=String(Math.max(1,Number(input.value||1)+1)));card.querySelector("[data-dec]")?.addEventListener("click",()=>input.value=String(Math.max(1,Number(input.value||1)-1)));card.querySelector("[data-add]")?.addEventListener("click",()=>{const id=card.dataset.id;cart[id]={id,name:card.dataset.name,unit:card.dataset.unit,quantity:Math.max(.01,Number(input.value||1))};save();open()})});function render(){const box=document.getElementById("drawerItems");if(!box)return;const arr=Object.values(cart);box.innerHTML=arr.length?arr.map(x=>'<div class="drawerItem"><strong>'+escapeHtml(x.name)+'</strong><div class="row"><input style="width:90px" type="number" min=".01" step=".01" value="'+x.quantity+'" data-cart-qty="'+escapeHtml(x.id)+'"><span>'+escapeHtml(x.unit)+'</span><button type="button" data-cart-remove="'+escapeHtml(x.id)+'">Sil</button></div></div>').join(""):'<p>Henüz ürün eklemediniz.</p>';box.querySelectorAll("[data-cart-qty]").forEach(i=>i.onchange=()=>{cart[i.dataset.cartQty].quantity=Math.max(.01,Number(i.value||1));save()});box.querySelectorAll("[data-cart-remove]").forEach(b=>b.onclick=()=>{delete cart[b.dataset.cartRemove];save()})}function escapeHtml(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}document.getElementById("quoteForm")?.addEventListener("submit",async e=>{e.preventDefault();const st=document.getElementById("quoteStatus"),fd=new FormData(e.target),items=Object.values(cart);if(!items.length){st.textContent="En az bir ürün seçmelisiniz.";return}const payload={customer:{name:fd.get("name"),business:fd.get("business"),phone:fd.get("phone"),email:fd.get("email")},note:fd.get("note"),consent:{kvkk:fd.get("consent")==="on",textVersion:"2026-09-29-v1",purpose:"QUOTE_REQUEST",acceptedAt:new Date().toISOString()},products:items};st.textContent="Gönderiliyor...";try{const r=await fetch("/api/quote",{method:"POST",headers:{"content-type":"application/json","accept":"application/json"},body:JSON.stringify(payload)});const j=await r.json();if(!r.ok||!j.ok)throw Error(j.message||"Teklif gönderilemedi.");st.textContent=(j.message||"Teklif talebiniz alındı.")+(j.quoteNo?" Talep No: "+j.quoteNo:"");cart={};save();e.target.reset()}catch(err){st.textContent=err.message||"Teklif gönderilemedi."}});counts();render()})();</script>`;
}
async function productsPage(env,url){
  const q=clean(url.searchParams.get("q"),100),category=clean(url.searchParams.get("category"),120); const list=await products(env,{q,category});
  const body=`<div class="sectionHead"><div><h2>${category?esc(category):"Tüm Ürünler"}</h2><p>${q?`Arama: ${esc(q)}`:"Ürün seçin, miktarı belirleyin ve teklif listenize ekleyin."}</p></div><span>${list.length} ürün</span></div><div class="products">${(list.length?list:demoProducts()).map(productCard).join("")}</div>`;
  return shell(body,"Ürünler | Okyanus EDT","Okyanus EDT profesyonel mutfak ürün kataloğu.","/urunler");
}
async function quoteAPI(request,env){
  await ensureCoreSchema(env); const body=await readJson(request,180000); const c=body.customer||{},name=clean(c.name,120),business=clean(c.business,160),phone=clean(c.phone,30),email=clean(c.email,160),note=clean(body.note,3000),items=Array.isArray(body.products)?body.products:[];
  if(!name||!phone||!email||body?.consent?.kvkk!==true||!items.length)return json({ok:false,error:"MISSING_FIELDS",message:"Müşteri bilgileri, KVKK onayı ve en az bir ürün zorunludur."},400);
  if(!validPhone(phone)||!validEmail(email))return json({ok:false,error:"INVALID_CONTACT",message:"Telefon veya e-posta bilgisini kontrol edin."},400);
  if(items.length>100)return json({ok:false,error:"TOO_MANY_ITEMS",message:"Teklif listesi en fazla 100 ürün olabilir."},400);
  const id=uuid(),no=quoteNo();
  const statements=[env.DB.prepare(`INSERT INTO quote_requests(id,quote_no,name,business,phone,email,note,consent_version,source) VALUES(?,?,?,?,?,?,?,?,?)`).bind(id,no,name,business,phone,email,note,clean(body?.consent?.textVersion,40),"WEB")];
  for(const x of items){const qty=Number(x.quantity||1);if(!Number.isFinite(qty)||qty<=0)continue;statements.push(env.DB.prepare(`INSERT INTO quote_items(id,quote_id,product_id,product_name,quantity,unit) VALUES(?,?,?,?,?,?)`).bind(uuid(),id,clean(x.id,120),clean(x.name,220),qty,clean(x.unit||"Adet",40)))}
  if(statements.length<2)return json({ok:false,error:"INVALID_ITEMS",message:"Ürün miktarlarını kontrol edin."},400);
  await env.DB.batch(statements); await audit(env,{action:"QUOTE_CREATED",entityType:"quote",entityId:id,detail:{quoteNo:no,count:statements.length-1}});
  const text=`Okyanus EDT teklif talebi\nTalep No: ${no}\nAd: ${name}\nİşletme: ${business}\nTelefon: ${phone}\nE-posta: ${email}\n\nÜrünler:\n${items.map(x=>`- ${clean(x.name,160)}: ${Number(x.quantity||1)} ${clean(x.unit||"Adet",30)}`).join("\n")}\n\nNot: ${note}`;
  let delivery="RECORDED";
  try{if(env?.EMAIL?.send)await sendBoundEmail(env,{replyTo:email,subject:`Okyanus EDT Teklif • ${no}`,text});else if(env?.QUOTE_WEBHOOK_URL)await postWebhook(env.QUOTE_WEBHOOK_URL,{type:"quote",quoteNo:no,name,business,phone,email,note,products:items});else delivery="WAITING_CONFIGURATION"}catch(e){delivery="NOTIFY_FAILED";console.error("QUOTE_NOTIFY_FAILED",no,String(e))}
  return json({ok:true,quoteNo:no,message:"Teklif talebiniz alındı.",delivery},201);
}
async function contactAPI(request,env){
  await ensureCoreSchema(env); const b=await readJson(request,100000),name=clean(b.name||[b.firstName,b.lastName].filter(Boolean).join(" "),120),business=clean(b.business,160),phone=clean(b.phone,30),email=clean(b.email,160),subject=clean(b.subject||"Genel Bilgi",120),message=clean(b.message,5000);
  if(!name||!phone||!email||!message||b.consent!==true)return json({ok:false,error:"MISSING_FIELDS",message:"Zorunlu bilgiler veya iletişim onayı eksik."},400);
  if(!validPhone(phone)||!validEmail(email))return json({ok:false,error:"INVALID_CONTACT",message:"Telefon veya e-posta bilgisini kontrol edin."},400);
  const id=uuid(),no=messageNo(); await env.DB.prepare(`INSERT INTO contact_messages(id,message_no,name,business,phone,email,subject,message) VALUES(?,?,?,?,?,?,?,?)`).bind(id,no,name,business,phone,email,subject,message).run();
  await audit(env,{action:"CONTACT_CREATED",entityType:"contact",entityId:id,detail:{messageNo:no}});
  const text=`Okyanus EDT iletişim formu\nMesaj No: ${no}\nAd: ${name}\nİşletme: ${business}\nTelefon: ${phone}\nE-posta: ${email}\nKonu: ${subject}\n\nMesaj:\n${message}`;
  let delivery="RECORDED";try{if(env?.EMAIL?.send)await sendBoundEmail(env,{replyTo:email,subject:`Okyanus EDT İletişim • ${subject} • ${no}`,text});else if(env?.CONTACT_WEBHOOK_URL||env?.QUOTE_WEBHOOK_URL)await postWebhook(env.CONTACT_WEBHOOK_URL||env.QUOTE_WEBHOOK_URL,{type:"contact",messageNo:no,name,business,phone,email,subject,message});else delivery="WAITING_CONFIGURATION"}catch(e){delivery="NOTIFY_FAILED";console.error("CONTACT_NOTIFY_FAILED",no,String(e))}
  return json({ok:true,messageNo:no,message:"Mesajınız başarıyla kaydedildi.",delivery},201);
}
function detectMime(b){
  if(b.length>12&&b[0]===0xff&&b[1]===0xd8&&b[2]===0xff)return"image/jpeg";
  if(b.length>8&&b[0]===0x89&&b[1]===0x50&&b[2]===0x4e&&b[3]===0x47)return"image/png";
  if(b.length>12&&String.fromCharCode(...b.slice(0,4))==="RIFF"&&String.fromCharCode(...b.slice(8,12))==="WEBP")return"image/webp";
  return"";
}
async function photoAPI(request,env){
  await ensureCoreSchema(env); if(!env?.PHOTO_TEMP||typeof env.PHOTO_TEMP.put!=="function")return json({ok:false,error:"PHOTO_STORE_NOT_BOUND",message:"Fotoğraf depolama yapılandırılmamış."},503);
  const ct=request.headers.get("content-type")||"";if(!ct.includes("multipart/form-data"))return json({ok:false,error:"INVALID_CONTENT_TYPE"},415);
  const fd=await request.formData(),file=fd.get("photo")||fd.get("file"),name=clean(fd.get("name"),120),business=clean(fd.get("business"),160),phone=clean(fd.get("phone"),30),email=clean(fd.get("email"),160),note=clean(fd.get("note"),3000),idempotency=clean(fd.get("idempotencyKey")||uuid(),120);
  if(!file||typeof file.arrayBuffer!=="function"||!name||!phone||!email)return json({ok:false,error:"MISSING_FIELDS",message:"Fotoğraf ve iletişim bilgileri zorunludur."},400);
  if(!validPhone(phone)||!validEmail(email))return json({ok:false,error:"INVALID_CONTACT"},400);
  if(file.size>8388608)return json({ok:false,error:"FILE_TOO_LARGE",message:"Fotoğraf en fazla 8 MB olabilir."},413);
  const bytes=new Uint8Array(await file.arrayBuffer()),mime=detectMime(bytes);if(!mime)return json({ok:false,error:"INVALID_IMAGE",message:"JPEG, PNG veya WebP fotoğraf yükleyin."},415);
  const existing=await env.DB.prepare(`SELECT request_no FROM photo_inquiries WHERE idempotency_key=? LIMIT 1`).bind(idempotency).first();if(existing)return json({ok:true,requestNo:existing.request_no,duplicate:true},200);
  const id=uuid(),no=photoNo(),ext=mime==="image/jpeg"?"jpg":mime==="image/png"?"png":"webp",key=`photo-inquiries/${new Date().toISOString().slice(0,10)}/${id}.${ext}`;
  await env.PHOTO_TEMP.put(key,bytes,{httpMetadata:{contentType:mime},customMetadata:{requestNo:no}});
  try{await env.DB.prepare(`INSERT INTO photo_inquiries(id,request_no,idempotency_key,name,business,phone,email,note,object_key,mime,size_bytes) VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(id,no,idempotency,name,business,phone,email,note,key,mime,bytes.byteLength).run()}catch(e){await env.PHOTO_TEMP.delete(key).catch(()=>{});throw e}
  await audit(env,{action:"PHOTO_INQUIRY_CREATED",entityType:"photo_inquiry",entityId:id,detail:{requestNo:no,key}});
  let delivery="RECORDED";const text=`Okyanus EDT fotoğraflı teklif talebi\nTalep No: ${no}\nAd: ${name}\nİşletme: ${business}\nTelefon: ${phone}\nE-posta: ${email}\nNot: ${note}\nDosya: ${key}`;
  try{if(env?.EMAIL?.send)await sendBoundEmail(env,{replyTo:email,subject:`Okyanus EDT Fotoğraflı Talep • ${no}`,text});else if(env?.PHOTO_WEBHOOK_URL||env?.QUOTE_WEBHOOK_URL)await postWebhook(env.PHOTO_WEBHOOK_URL||env.QUOTE_WEBHOOK_URL,{type:"photo",requestNo:no,name,business,phone,email,note,key});else delivery="WAITING_CONFIGURATION";await env.DB.prepare(`UPDATE photo_inquiries SET notify_status=? WHERE id=?`).bind(delivery==="RECORDED"?"SENT":delivery,id).run()}catch(e){delivery="NOTIFY_FAILED";await env.DB.prepare(`UPDATE photo_inquiries SET notify_status='FAILED' WHERE id=?`).bind(id).run();console.error("PHOTO_NOTIFY_FAILED",no,String(e))}
  return json({ok:true,requestNo:no,message:"Fotoğraflı talebiniz alındı.",delivery},201);
}
