async function memberAPI(request,env,path){
  await ensureCoreSchema(env);
  if(path==="/api/member/register"&&request.method==="POST"){
    if(!sameOrigin(request))return json({ok:false,error:"ORIGIN_REJECTED"},403);
    const b=await readJson(request,100000),email=clean(b.email,160).toLowerCase(),name=clean(b.name||b.displayName,120),business=clean(b.business||b.businessName,160),phone=clean(b.phone,30),password=String(b.password||"");
    if(!validEmail(email)||!name||!business||password.length<10||b.terms!==true)return json({ok:false,error:"INVALID_REGISTRATION",message:"Bilgileri, kullanım koşullarını ve en az 10 karakterlik parolayı kontrol edin."},400);
    const exists=await env.DB.prepare(`SELECT id FROM members WHERE email=? LIMIT 1`).bind(email).first();if(exists)return json({ok:false,error:"EMAIL_EXISTS"},409);
    const id=uuid(),businessId=uuid(),hash=await hashPassword(password);await env.DB.prepare(`INSERT INTO members(id,business_id,email,display_name,business_name,phone,password_hash) VALUES(?,?,?,?,?,?,?)`).bind(id,businessId,email,name,business,phone,hash).run();await audit(env,{actor:id,action:"MEMBER_REGISTERED",entityType:"member",entityId:id});
    return json({ok:true,message:"Hesabınız oluşturuldu."},201);
  }
  if(path==="/api/member/login"&&request.method==="POST"){
    if(!sameOrigin(request))return json({ok:false,error:"ORIGIN_REJECTED"},403);if(!env?.SESSION_PEPPER)return json({ok:false,error:"SESSION_SECRET_MISSING"},503);
    const b=await readJson(request,50000),email=clean(b.email,160).toLowerCase(),password=String(b.password||""),m=await env.DB.prepare(`SELECT * FROM members WHERE email=? LIMIT 1`).bind(email).first();
    if(!m||m.status!=="active"||!(await verifyPassword(password,m.password_hash)))return json({ok:false,error:"INVALID_CREDENTIALS"},401);
    const raw=crypto.randomUUID()+crypto.randomUUID(),tokenHash=await sha256(raw+env.SESSION_PEPPER),id=uuid(),expires=new Date(Date.now()+8*3600e3).toISOString();await env.DB.prepare(`INSERT INTO member_sessions(id,member_id,token_hash,expires_at) VALUES(?,?,?,?)`).bind(id,m.id,tokenHash,expires).run();await audit(env,{actor:m.id,action:"LOGIN",entityType:"session",entityId:id});
    return json({ok:true,user:{id:m.id,email:m.email,displayName:m.display_name,businessId:m.business_id,role:m.role}},200,{"set-cookie":memberCookie(raw,8*3600)});
  }
  if(path==="/api/member/logout"&&request.method==="POST"){
    const me=await memberSession(request,env);if(me)await env.DB.prepare(`UPDATE member_sessions SET revoked_at=datetime('now') WHERE id=?`).bind(me.session_id).run();
    return json({ok:true},200,{"set-cookie":memberCookie("",0)});
  }
  if(path==="/api/member/me"&&request.method==="GET"){const me=await memberSession(request,env);if(!me)return json({ok:false,error:"UNAUTHENTICATED"},401);return json({ok:true,user:{id:me.id,email:me.email,displayName:me.display_name,businessId:me.business_id,businessName:me.business_name,role:me.role}})}
  return json({ok:false,error:"NOT_FOUND"},404);
}
