function seoLanding(path){
 const label=path.slice(1).replaceAll("-"," ").replace(/\bedt\b/i,"EDT").replace(/\b\w/g,x=>x.toLocaleUpperCase("tr-TR"));
 return shell(`<section class="hero" style="min-height:230px"><h1>${esc(label)}</h1><p>Okyanus EDT profesyonel mutfak ürünlerini inceleyin, ürün seçin ve teklif listenizi oluşturun.</p><div class="ctas"><a class="btn blue" href="/urunler?source=seo">Ürünleri İncele</a><a class="btn green" href="/fotografla-teklif">Fotoğrafla Teklif Al</a></div></section>`,`${label} | Okyanus EDT`,`${label}. Profesyonel mutfak ürünleri ve teklif.`,path);
}
function robots(){return `User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /benim-okyanusum\nDisallow: /uye\nDisallow: /dijital-menu\nSitemap: https://www.okyonusedt.com/sitemap.xml\n`}
function sitemap(){
 const base="https://www.okyonusedt.com";const routes=["/","/urunler","/fotografla-teklif","/iletisim",...LEGACY_SEO_ROUTES];
 return `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${[...new Set(routes)].map(x=>`<url><loc>${base}${x}</loc></url>`).join("")}</urlset>`;
}
async function asset(env,path){
 if(!env?.MEDIA_STORE||typeof env.MEDIA_STORE.get!=="function")return new Response("Not found",{status:404});
 const key=decodeURIComponent(path.slice("/assets/".length));if(!/^[a-zA-Z0-9_./-]{1,300}$/.test(key))return new Response("Not found",{status:404});
 const obj=await env.MEDIA_STORE.get(key);if(!obj)return new Response("Not found",{status:404});
 const h=new Headers();obj.writeHttpMetadata?.(h);h.set("etag",obj.httpEtag||"");h.set("cache-control","public, max-age=86400");return new Response(obj.body,{headers:h});
}
export default {
 async fetch(request,env,ctx){
  try{
   const url=new URL(request.url);let path=url.pathname.length>1&&url.pathname.endsWith("/")?url.pathname.slice(0,-1):url.pathname;
   if(url.hostname==="okyonusedt.com"){url.hostname="www.okyonusedt.com";url.protocol="https:";return Response.redirect(url.toString(),301)}
   if(path!==url.pathname){url.pathname=path;return Response.redirect(url.toString(),301)}
   const headers=securityHeaders();
   if(request.method==="OPTIONS")return new Response(null,{status:204,headers});
   if(path.startsWith("/assets/category/")){const embedded=embeddedCategoryAsset(path);if(embedded)return embedded}if(path.startsWith("/assets/"))return asset(env,path);
   if(path==="/health")return json({ok:true,app:"OKYONUS_DENIZ",build:BUILD,features:ACTIVE_PUBLIC_FEATURES,db:!!env.DB,photo:!!env.PHOTO_TEMP,email:!!env.EMAIL});
   if(path==="/robots.txt")return new Response(robots(),{headers:{"content-type":"text/plain; charset=utf-8","cache-control":"public, max-age=3600"}});
   if(path==="/sitemap.xml")return new Response(sitemap(),{headers:{"content-type":"application/xml; charset=utf-8","cache-control":"public, max-age=3600"}});
   if(path==="/api/products"&&request.method==="GET")return json({ok:true,products:await products(env,{q:clean(url.searchParams.get("q"),100),category:clean(url.searchParams.get("category"),120)})});
   if(path==="/api/quote"&&request.method==="POST")return quoteAPI(request,env);
   if(path==="/api/contact"&&request.method==="POST")return contactAPI(request,env);
   if(path==="/api/photo-inquiries"&&request.method==="POST")return photoAPI(request,env);
   if(path.startsWith("/api/member/"))return memberAPI(request,env,path);
   if(path==="/api/digital-menu")return digitalMenuAPI(request,env,url);
   if(request.method!=="GET"&&request.method!=="HEAD")return json({ok:false,error:"METHOD_NOT_ALLOWED"},405);
   if(path==="/")return html(await homePage(env),200,headers);
   if(path==="/urunler")return html(await productsPage(env,url),200,headers);
   if(path==="/fotografla-teklif")return html(photoPage(),200,headers);
   if(path==="/iletisim")return html(contactPage(),200,headers);
   if(path==="/uye"||path==="/uyelik")return html(memberPage(),200,{...headers,"x-robots-tag":"noindex,follow"});
   if(path==="/benim-okyanusum")return html(await memberWorkspace(request,env),200,{...headers,"x-robots-tag":"noindex,follow"});
   if(path==="/dijital-menu")return html(await digitalMenuPage(request,env),200,{...headers,"x-robots-tag":"noindex,follow"});
   if(path.startsWith("/menu/"))return html(await publicMenu(env,decodeURIComponent(path.slice(6))),200,headers);
   if(path==="/yardim"||path==="/help")return html(helpPage(),200,headers);
   if(path==="/kvkk")return html(shell(`<section><div class="sectionHead"><div><h2>KVKK ve Gizlilik</h2><p>Veri işleme süreçleri amaçla sınırlılık ve veri minimizasyonu ilkeleriyle yürütülür.</p></div></div></section>`,"KVKK | Okyanus EDT","KVKK bilgilendirmesi.","/kvkk"),200,headers);
   if(LEGACY_SEO_ROUTES.includes(path))return html(seoLanding(path),200,headers);
   if(["/cost","/cost-hesaplama","/cost-radar","/akademi","/academy","/cesni"].includes(path))return html(shell(`<section><div class="sectionHead"><div><h2>Bu modül şu anda yayında değil</h2><p>Okyanus satış deneyimi sadeleştirilmiştir. Modül verileri korunmaktadır.</p></div></div><a class="btn blue" href="/">Ana Sayfaya Dön</a></section>`,"Okyanus EDT","Modül pasif.","/"),404,{"x-robots-tag":"noindex,nofollow"});
   return json({ok:false,error:"NOT_FOUND"},404);
  }catch(error){console.error("OKYONUS_DENIZ_ERROR",error?.stack||error);return json({ok:false,error:error?.message||"INTERNAL_ERROR"},error?.status||500)}
 },
 async scheduled(event,env,ctx){void event;const task=(async()=>{if(!env?.DB)return;await ensureCoreSchema(env);await env.DB.prepare(`DELETE FROM member_sessions WHERE expires_at<datetime('now','-1 day')`).run()})();ctx?.waitUntil?.(task);return task}
};